const x=$json||{};
let text=String(x.tekst_ishodnyy_dlya_obrabotki??x.tekst??'');
const existing=Array.isArray(x.pii_slovar)?x.pii_slovar:[];
const known={};
for(const z of existing){
  const p=String(z?.psevdometka||'').trim();
  const v=z?.znachenie_zashchishchennoe;
  if(p&&v!==null&&v!==undefined&&String(v)!=='') known[p]=String(v);
}
const candidates=[];
const used=new Set(Object.keys(known));
function esc(s){return String(s).replace(/[-/\^$*+?.()|[\]{}]/g,'\\$&')}
function existingToken(tip,val){
  for(const z of existing){
    if(String(z?.tip_pii||'')===tip&&String(z?.znachenie_zashchishchennoe||'')===String(val)) return String(z.psevdometka||'');
  }
  return '';
}
function next(prefix,tip,val,extra={}){
  const old=existingToken(tip,val);
  if(old) return old;
  let n=1,p;
  do{p='<'+prefix+'_'+n+'>';n++;}while(used.has(p));
  used.add(p);
  known[p]=String(val);
  candidates.push({tip_pii:tip,psevdometka:p,znachenie_zashchishchennoe:String(val),...extra});
  return p;
}
for(const [p,v] of Object.entries(known)){
  if(String(v).length>=2) text=text.replace(new RegExp(esc(v),'gi'),p);
}
text=text.replace(/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi,m=>next('EMAIL','email',m));
text=text.replace(/(?<!\w)(?:\+?\d[\d\s().-]{8,}\d)(?!\w)/g,m=>next('TELEFON','telefon',m,{region_telefona:x._nastroyki?.bezopasnost?.region_telefona||null}));
text=text.replace(/(?<!\w)@[A-Za-z0-9_]{5,32}\b/g,m=>next('USERNAME','telegram_username',m));
text=text.replace(/\b(меня\s+зовут|мо[её]\s+имя)\s+([А-ЯЁA-Z][А-ЯЁA-Za-zа-яё-]{1,40})/gi,(m,p,n)=>p+' '+next('PERSON','imya',n));
return [{json:{...x,tekst_bez_pii:text.trim(),pii_kandidaty:candidates,pii_slovar:[...existing,...candidates]}}];

